import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.DYqHduS5.js";const u=JSON.parse('{"title":"BridgeLite とは","description":"","frontmatter":{},"headers":[],"relativePath":"ja/introduction.md","filePath":"ja/introduction.md"}'),i={name:"ja/introduction.md"};function o(n,t,h,l,p,s){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="bridgelite-とは" tabindex="-1">BridgeLite とは <a class="header-anchor" href="#bridgelite-とは" aria-label="Permalink to &quot;BridgeLite とは&quot;">​</a></h1><p>BridgeLite は、RAW+JPG 同時撮影をするフォトグラファーのための<strong>軽量画像セレクトビュワー</strong>です。</p><p>撮影後のフォルダには、撮って出し・RAW・現像済みが混在します。どれが現像済みで、どれがまだか——気づけば把握できなくなっていることがあります。BridgeLite でフォルダを開けば、三種の状態と評価がひと目でわかります。</p><h2 id="できること" tabindex="-1">できること <a class="header-anchor" href="#できること" aria-label="Permalink to &quot;できること&quot;">​</a></h2><p>BridgeLite がやることは3つだけです。</p><ul><li><strong>見る</strong> — サムネイルグリッドで大量の写真を素早くスクロール</li><li><strong>評価する</strong> — キーボードショートカットで 0〜5 星の XMP レーティングを高速に付ける</li><li><strong>比べる</strong> — 撮って出し・RAW・現像済みをひとつのグループとして行き来する</li></ul><p>現像やレタッチなどは、いつも使っているツールをご活用ください。評価は Lightroom や Capture One にそのまま引き継げます。</p><h2 id="グルーピング機能" tabindex="-1">グルーピング機能 <a class="header-anchor" href="#グルーピング機能" aria-label="Permalink to &quot;グルーピング機能&quot;">​</a></h2><p>現像した結果が、いつも正解とは限りません。カメラ出力の方が素直に良かったり、現像を重ねるうちに元の色調を見失ってしまうことも。BridgeLite ではこれらの過程を、ひとつのグループとして扱うことができます。</p><h2 id="可搬性のある設計" tabindex="-1">可搬性のある設計 <a class="header-anchor" href="#可搬性のある設計" aria-label="Permalink to &quot;可搬性のある設計&quot;">​</a></h2><p>BridgeLite は独自のデータベースを持ちません。評価などの情報はすべて XMP サイドカーに書き込まれるため、Lightroom や Capture One など、どのソフトウェアからでも読み書きできます。BridgeLite を使わなくなっても、写真のデータはそのまま残ります。</p><h2 id="何をしないか" tabindex="-1">何をしないか <a class="header-anchor" href="#何をしないか" aria-label="Permalink to &quot;何をしないか&quot;">​</a></h2><p>現像・色補正・書き出し・リサイズは行いません。それらはすでにあなたが使っている Lightroom や Capture One などの現像ツールに委ねます。</p><p>BridgeLite は独自のカタログやデータベースを持ちません。写真の管理はファイルシステムが主体であり、BridgeLite を使わなくなっても写真データはそのまま残ります。ただし、サムネイルの表示や評価によるフィルタリングを高速に行うため、内部的に SQLite キャッシュを使用しています。このキャッシュはいつでも削除でき、削除しても写真データや評価情報には影響しません。</p><h2 id="xmp-の書き込みについて" tabindex="-1">XMP の書き込みについて <a class="header-anchor" href="#xmp-の書き込みについて" aria-label="Permalink to &quot;XMP の書き込みについて&quot;">​</a></h2><p>閲覧・スクロール・フィルタリングのいかなる操作においても、画像の画素データや EXIF 情報は一切変更しません。メモリカードやネットワークドライブからも安心して使えます。</p><p>レーティングなどの XMP 情報は、ファイル種別によって書き込み方式が異なります。</p><table tabindex="0"><thead><tr><th>ファイル種別</th><th>デフォルト</th><th>オプション</th></tr></thead><tbody><tr><td>JPG</td><td>ファイル内の XMP 領域に埋め込み</td><td>サイドカー方式（<code>.xmp</code>）に変更可</td></tr><tr><td>RAW</td><td>サイドカー方式（<code>.xmp</code>）</td><td>—</td></tr></tbody></table><p>RAW ファイルは仕様上 XMP を直接書き込めないため、常にサイドカー方式になります。JPG はデフォルトで埋め込み方式ですが、設定でサイドカー方式に切り替えることができます。</p><h2 id="動作環境" tabindex="-1">動作環境 <a class="header-anchor" href="#動作環境" aria-label="Permalink to &quot;動作環境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>要件</th></tr></thead><tbody><tr><td>OS</td><td>macOS 14 Sonoma 以降</td></tr><tr><td>チップ</td><td>Apple Silicon（M1 以降）</td></tr><tr><td>価格</td><td>無料（MIT ライセンス）</td></tr></tbody></table>',21)])])}const b=e(i,[["render",o]]);export{u as __pageData,b as default};
